.iconbutton {
  display: inline-flex;
  flex-direction: row;
  align-items: center;
  justify-content: center;
  gap: var(--space-xs);
  padding: var(--space-sm) var(--space-md) var(--space-sm) var(--space-md);
  background: var(--color-action-bg);
  border-radius: var(--radius-md);
  width: max-content;
  height: max-content;
}

.iconbutton .icon,
.iconbutton .chevron {
  display: inline-flex;
  width: max-content;
  height: max-content;
}

.iconbutton .label {
  display: inline-flex;
  width: max-content;
  height: max-content;
  color: var(--color-action-fg);
  font-family: var(--typo-label-md-fontFamily);
  font-size: var(--typo-label-md-fontSize);
  font-weight: var(--typo-label-md-fontWeight);
  line-height: var(--typo-label-md-lineHeight);
}

/* gap overrides by size */
.iconbutton[data-variant*="size=md"] { gap: var(--space-sm); }
.iconbutton[data-variant*="size=lg"] { gap: var(--space-md); }

/* background overrides by state */
.iconbutton[data-variant*="state=hover"] { background: var(--color-action-border); }
.iconbutton[data-variant*="state=disabled"] { background: var(--color-surface-muted); }
